import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    my_c = sum(1 for a in me if a == 'C')
    op_c = sum(1 for a in op if a == 'C')
    my_d = n - my_c
    op_d = n - op_c

    # Late-game exploitation of a clearly cooperative opponent.
    if n >= 90:
        if op_d <= 2:
            return 'D'
        if op_d * 10 <= n and op[-1] == 'C':
            return 'D'

    # Deep-endgame: defect if opponent is not purely cooperative but we can gain.
    if n >= 97 and op_d >= 3:
        return 'D'

    # Pure cooperator: exploit mildly in mid/late game, but keep most points.
    if op_d == 0:
        if n < 15:
            return 'C'
        if n >= 70 and rng.random() < 0.6:
            return 'D'
        if n >= 40 and rng.random() < 0.1:
            return 'D'
        return 'C'

    # All-defector or near all-defector: protect.
    if op_c == 0:
        if n >= 6 and op[-1] == 'C':
            return 'C'
        return 'D'

    # Strong defector detection.
    if op_d >= op_c + 4 or (n >= 8 and op_d * 3 >= n * 2):
        if op[-1] == 'C' and rng.random() < 0.25:
            return 'C'
        return 'D'

    recent = history[-8:] if n >= 8 else history
    r_cc = r_cd = r_dc = r_dd = 0
    for a, b in recent:
        if a == 'C' and b == 'C':
            r_cc += 1
        elif a == 'C' and b == 'D':
            r_cd += 1
        elif a == 'D' and b == 'C':
            r_dc += 1
        else:
            r_dd += 1
    rlen = len(recent)
    r_opp_d = r_cd + r_dd
    r_opp_c = r_cc + r_dc

    # Death-spiral breaker.
    if r_dd >= 4 and r_cc == 0:
        if my_d >= 3 and rng.random() < 0.6:
            return 'C'

    last_me, last_op = history[-1]

    # Opponent just cooperated.
    if last_op == 'C':
        if r_dc >= 2 and r_cc >= 1 and n < 90:
            if rng.random() < 0.35:
                return 'D'
        return 'C'

    # Opponent just defected.
    if r_opp_c >= 6 and rlen >= 8:
        if rng.random() < 0.35:
            return 'C'
    if r_dd >= 3:
        if rng.random() < 0.15:
            return 'C'
        return 'D'
    if last_me == 'D':
        if rng.random() < 0.5:
            return 'C'
        return 'D'
    if rng.random() < 0.12:
        return 'C'
    return 'D'
